import{_ as l,a0 as o,w as n,s,ao as S,I as p,x as t,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"学习 ReactJS 之前，你需要了解多少 JavaScript？ | LCTT x X-CMD","titleTemplate":false,"description":"学习 ReactJS 之前，你需要了解多少 JavaScript？ | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"学习 ReactJS 之前，你需要了解多少 JavaScript？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"学习 ReactJS 之前，你需要了解多少 JavaScript？ | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220720 How much JavaScript do you need to know before learning ReactJS-","title":"学习 ReactJS 之前，你需要了解多少 JavaScript？","tag":"202207","desc":""},"relativePath":"202207/20220720 How much JavaScript do you need to know before learning ReactJS-.md","filePath":"[post].md"}'),c={name:"202207/20220720 How much JavaScript do you need to know before learning ReactJS-.md"};function d(J,a,u,v,m,f){const e=o("Link");return n(),s("div",null,[a[18]||(a[18]=S('<h1 id="学习-reactjs-之前-你需要了解多少-javascript" tabindex="-1">学习 ReactJS 之前，你需要了解多少 JavaScript？ <a class="header-anchor" href="#学习-reactjs-之前-你需要了解多少-javascript" aria-label="Permalink to “学习 ReactJS 之前，你需要了解多少 JavaScript？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202207/29/082104d5zn1xn77r1n8p1n.jpg" alt=""></p><blockquote><p>最主要的是要精通 JavaScript，这样你就可以减少 ReactJS 之旅的复杂性。</p></blockquote><p>React 是一个建立在 HTML、CSS 和 JavaScript 之上的 UI 框架，其中 JavaScript（JS）负责大部分的逻辑。如果你对变量、数据类型、数组函数、回调、作用域、字符串方法、循环和其他 JS DOM 操作相关的主题有一定了解，这些将极大地加快学习 ReactJS 的步伐。</p><p>你对现代 JavaScript 的概念将决定你能多快地掌握 ReactJS 的步伐。你不需要成为一个 JavaScript 专家来开始你的 ReactJS 之旅，但就像对食材的了解是任何希望掌握烹饪的厨师所必须的一样，学习 ReactJS 也是如此。它是一个现代的 JavaScript UI 库，所以你需要了解一些 JavaScript。问题是，需要多少？</p><h3 id="示例解释" tabindex="-1">示例解释 <a class="header-anchor" href="#示例解释" aria-label="Permalink to “示例解释”">​</a></h3><p>假设我被要求用英语写一篇关于“牛”的文章，但我对这种语言一无所知。在这种情况下，为了让我成功地完成任务，我不仅要对主题有概念，还要对指定的语言有概念。</p><p>假设我获得了一些关于主题（牛）的知识，我如何计算我需要知道多少英语才能写出规定的主题？如果我必须用英语写一篇关于其他复杂话题的文章呢？</p><p>这很难搞清楚，不是吗？我不知道我要写关于这个话题的什么东西，但它可能是任何东西。所以要想开始，我必须要有适当的英语知识，但还不止于此。</p><h3 id="极端现实" tabindex="-1">极端现实 <a class="header-anchor" href="#极端现实" aria-label="Permalink to “极端现实”">​</a></h3><p>在开始使用 ReactJS 之前，所需的 JavaScript 数量也是如此。根据我的例子情景，ReactJS 是话题“牛”，而 JavaScript 是英语。要想在 ReactJS 中获得成功，对 JavaScript 的掌握很重要。如果没有适当的 JavaScript 基础，一个人是很难专业地掌握 ReactJS 的。无论我对这个主题有多少知识，如果我不知道语言的基础，我就不能正确地表达自己。</p><h3 id="多少才算够" tabindex="-1">多少才算够？ <a class="header-anchor" href="#多少才算够" aria-label="Permalink to “多少才算够？”">​</a></h3><p>根据我的经验，当你开始你的 ReactJS 之旅时，你应该已经熟悉了：</p><ul><li>变量</li><li>数据类型</li><li>字符串方法</li><li>循环</li><li>条件式</li></ul><p>你应该对这些具体的 JavaScript 熟悉。但这些只是最基本的先决条件。当你试图创建一个简单的 React 应用时，你将不可避免地需要处理事件。所以，普通函数、函数表达式、语句、箭头函数的概念，箭头函数和普通函数的区别，以及这两类函数中 <code>this</code> 关键字的词义范围，这确实很重要。</p><p>但问题是，如果我必须使用 ReactJS 创建一个复杂的应用怎么办？</p><h3 id="获得启发" tabindex="-1">获得启发 <a class="header-anchor" href="#获得启发" aria-label="Permalink to “获得启发”">​</a></h3><p>在 JavaScript 中处理事件、传播操作符、解构、命名导入和默认导入将帮助你理解 React 代码的工作机制。</p><p>最重要的是，你必须了解 JavaScript 本身背后的核心概念。JavaScript 在设计上是异步的。当出现在文件底部的代码在文件顶部的代码之前执行时，不要惊讶。像 promise、callback、async-await、map、filter 和 reduce 这样的结构，是 ReactJS 中最常见的方法和概念，尤其是在开发复杂的应用时。</p><p>最主要的是要精通 JavaScript，这样你可以减少 ReactJS 之旅的复杂性。</p><h3 id="越来越好" tabindex="-1">越来越好 <a class="header-anchor" href="#越来越好" aria-label="Permalink to “越来越好”">​</a></h3><p>我很容易说出你需要知道的东西，但你去学习它完全是另一回事。大量练习 JavaScript 是必不可少的，但你可能会感到惊讶，我认为这并不意味着你必须等到掌握它。有些概念事先很重要，但你可以在学习过程中学到很多东西。练习的一部分是学习，所以你可以开始使用 JavaScript，甚至是 React 的一些基础知识，只要你以舒适的速度移动并理解在你尝试任何严肃的事情之前做你的“家庭作业”是一个要求。</p><h3 id="立即开始使用-javascript" tabindex="-1">立即开始使用 JavaScript <a class="header-anchor" href="#立即开始使用-javascript" aria-label="Permalink to “立即开始使用 JavaScript”">​</a></h3>',23)),p("p",null,[a[1]||(a[1]=t("不要费心等到你了解了 JavaScript 的所有方面。那永远不会发生。如果这样做，你将陷入学习 JavaScript 的永远循环中。你们都知道技术领域是如何不断发展和迅速变化的。如果你想开始学习 JavaScript，请尝试阅读 Mandy Kendall 的介绍性文章 ",-1)),r(e,{href:"https://opensource.com/article/21/1/learn-javascript"},{default:i(()=>[...a[0]||(a[0]=[t("通过编写猜谜游戏学习 JavaScript",-1)])]),_:1}),a[2]||(a[2]=t("。这是一种快速入门的好方法，当你看到了可能的情况，我认为你可能会发现很难停下来。",-1))]),a[19]||(a[19]=p("hr",null,null,-1)),p("p",null,[a[4]||(a[4]=t("via: ",-1)),r(e,{href:"https://opensource.com/article/22/7/learn-javascript-before-reactjs"},{default:i(()=>[...a[3]||(a[3]=[t("https://opensource.com/article/22/7/learn-javascript-before-reactjs",-1)])]),_:1})]),p("p",null,[a[9]||(a[9]=t("作者：",-1)),r(e,{href:"https://opensource.com/users/sacsam005"},{default:i(()=>[...a[5]||(a[5]=[t("Sachin Samal",-1)])]),_:1}),a[10]||(a[10]=t(" 选题：",-1)),r(e,{href:"https://github.com/lkxed"},{default:i(()=>[...a[6]||(a[6]=[t("lkxed",-1)])]),_:1}),a[11]||(a[11]=t(" 译者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:i(()=>[...a[7]||(a[7]=[t("geekpi",-1)])]),_:1}),a[12]||(a[12]=t(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[8]||(a[8]=[t("wxy",-1)])]),_:1})]),p("p",null,[a[15]||(a[15]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[13]||(a[13]=[t("LCTT",-1)])]),_:1}),a[16]||(a[16]=t(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...a[14]||(a[14]=[t("Linux中国",-1)])]),_:1}),a[17]||(a[17]=t(" 荣誉推出",-1))])])}const x=l(c,[["render",d]]);export{b as __pageData,x as default};
